"""Render every .pdg under docs/ to an animated SVG next to its source.

Also writes one sample .pdg per bundled theme into docs/examples/themes/ first,
so the themes page always covers every theme predictygraph ships.
"""
import argparse
import sys
from pathlib import Path

from predictygraph import list_themes, scene_from_file, write_svg

THEME_SAMPLE = """\
# Generated by scripts/render_examples.py; edit the template there.
graph theme={theme} dir=LR route=bend

user "User"
group cluster "Cluster" layout=layered dir=TB {{
  api "API" .accent border=pulse
  sched "Scheduler"
  api -> sched
}}
group pool "GPU pool" layout=grid cols=2 {{
  g0 "GPU 0" .green; g1 "GPU 1" .green
  g2 "GPU 2" .yellow; g3 "GPU 3" .red
}}
db "Store" shape=cylinder .blue

user -> api flow=forward
sched -> pool .accent flow=forward
sched ..> db
"""


class ExampleRenderer:
    def __init__(self, root: Path):
        self.root = root
        self.failed: list[str] = []

    def write_theme_samples(self) -> None:
        out = self.root / "examples" / "themes"
        out.mkdir(parents=True, exist_ok=True)
        for theme in list_themes():
            (out / f"{theme}.pdg").write_text(THEME_SAMPLE.format(theme=theme), encoding="utf-8")

    def render(self, src: Path) -> None:
        name = src.relative_to(self.root)
        try:
            src.with_suffix(".svg").write_text(write_svg(scene_from_file(src), None), encoding="utf-8")
            print(f"ok   {name}")
        except Exception as exc:  # report every broken example, not just the first
            self.failed.append(f"{name}: {exc}")
            print(f"FAIL {name}: {exc}", file=sys.stderr)

    def run(self) -> int:
        self.write_theme_samples()
        for src in sorted(self.root.rglob("*.pdg")):
            self.render(src)
        return 1 if self.failed else 0


def main() -> int:
    ap = argparse.ArgumentParser(description=__doc__)
    ap.add_argument("root", nargs="?", type=Path, default=Path("docs"))
    return ExampleRenderer(ap.parse_args().root).run()


if __name__ == "__main__":
    sys.exit(main())
